#include <tora/integer/integer.hpp>
#include <cmath>
#include <algorithm>
#include <iostream>
#include <random>
#include <stdexcept>
using namespace tora;
void check(bool b){if(!b)throw std::runtime_error("Integer regression failed");}
void near(double a,double b){check(std::abs(a-b)<1e-7);}
bool feasible(const lp::LpProblem& p,const std::vector<double>& x){for(std::size_t j=0;j<x.size();++j)if(!p.variables[j].unrestricted && (x[j]<p.variables[j].lowerBound-1e-8 || x[j]>p.variables[j].upperBound+1e-8))return false;for(const auto& r:p.constraints){double lhs=0;for(std::size_t j=0;j<x.size();++j)lhs+=r.coefficients[j]*x[j];if(r.relation==lp::Relation::LessEqual?lhs>r.rhs+1e-8:r.relation==lp::Relation::GreaterEqual?lhs<r.rhs-1e-8:std::abs(lhs-r.rhs)>1e-8)return false;}return true;}
int main(){try{auto p=lp::LpProblem::blank(2,2);p.objective={3,2};p.constraints={{{2,1},lp::Relation::LessEqual,4.5},{{1,2},lp::Relation::LessEqual,4.5}};auto r=integer::solve({p,{true,true}});check(r.status==integer::Status::Optimal);near(*r.objective,6);check(r.nodes.size()>1);r=integer::solve({p,{true,false}});near(*r.objective,7);check(feasible(p,r.values));r=integer::solve({p,{true,true}},1);check(r.status==integer::Status::NodeLimit && !r.objective);
 // Guided branching chooses x2 first, explores the chosen pending node, and
 // preserves the best incumbent even when bound pruning is disabled.
 for(bool prune:{true,false}){integer::Session guided({p,{true,true}});guided.setBoundPruning(prune);guided.next();check(guided.awaitingBranch()==0);check(guided.result().nodes[0].state==integer::NodeState::AwaitingBranch);bool rejected=false;try{guided.branch(2);}catch(const std::invalid_argument&){rejected=true;}check(rejected && guided.awaitingBranch()==0);guided.branch(1);check(guided.pending().size()==2);check(guided.result().nodes[0].branchVariable==1);guided.next(0);while(!guided.finished()){if(auto index=guided.awaitingBranch()){const auto& values=guided.result().nodes[*index].values;std::size_t j=0;while(j<values.size() && std::abs(values[j]-std::round(values[j]))<1e-8)++j;guided.branch(j);}else guided.next();}check(guided.result().status==integer::Status::Optimal);near(*guided.result().objective,6);}
 auto oneFractional=lp::LpProblem::blank(2,2);oneFractional.objective={1,1};oneFractional.constraints={{{1,0},lp::Relation::LessEqual,1},{{0,1},lp::Relation::LessEqual,.5}};integer::Session rejectsIntegral({oneFractional,{true,true}});bool badPending=false;try{rejectsIntegral.next(1);}catch(const std::out_of_range&){badPending=true;}check(badPending && rejectsIntegral.pending().size()==1 && rejectsIntegral.result().nodes.empty());rejectsIntegral.next();bool integralRejected=false;try{rejectsIntegral.branch(0);}catch(const std::invalid_argument&){integralRejected=true;}check(integralRejected && rejectsIntegral.awaitingBranch()==0);rejectsIntegral.branch(1);
 integer::Session guidedMixed({p,{true,false}});guidedMixed.next();bool continuousRejected=false;try{guidedMixed.branch(1);}catch(const std::invalid_argument&){continuousRejected=true;}check(continuousRejected);guidedMixed.branch(0);
 integer::Session guidedLimit({p,{true,true}},1);guidedLimit.next();guidedLimit.branch(0);guidedLimit.next();check(guidedLimit.finished() && guidedLimit.result().status==integer::Status::NodeLimit);
 auto half=lp::LpProblem::blank(1,1);half.objective={1};half.constraints={{{1},lp::Relation::Equal,.5}};r=integer::solve({half,{true}});check(r.status==integer::Status::Infeasible && !r.objective);
 auto free=lp::LpProblem::blank(1,2);free.objective={1};free.variables[0].unrestricted=true;free.variables[0].lowerBound=-INFINITY;free.constraints={{{1},lp::Relation::LessEqual,2.5},{{1},lp::Relation::GreaterEqual,-2.5}};r=integer::solve({free,{true}});check(r.status==integer::Status::Optimal);near(*r.objective,2);
 std::mt19937 random(20261016);for(int sample=0;sample<300;++sample){auto q=lp::LpProblem::blank(2,3);q.title=std::to_string(sample);q.sense=sample%2?lp::ObjectiveSense::Minimize:lp::ObjectiveSense::Maximize;for(std::size_t j=0;j<2;++j){q.variables[j].lowerBound=-2;q.variables[j].upperBound=4;q.objective[j]=int(random()%9)-4;}for(auto& row:q.constraints){row.coefficients={double(int(random()%7)-3),double(int(random()%7)-3)};row.relation=random()%2?lp::Relation::LessEqual:lp::Relation::GreaterEqual;row.rhs=int(random()%15)-7;}
 std::optional<double> best;for(int x=-2;x<=4;++x)for(int y=-2;y<=4;++y){std::vector<double> point{double(x),double(y)};if(feasible(q,point)){const double value=q.objective[0]*x+q.objective[1]*y;if(!best || (q.sense==lp::ObjectiveSense::Maximize?value>*best:value<*best))best=value;}}
 const auto solved=integer::solve({q,{true,true}});check(solved.status==integer::Status::Optimal || solved.status==integer::Status::Infeasible);check(bool(solved.objective)==bool(best));if(best){near(*solved.objective,*best);check(feasible(q,solved.values));for(auto x:solved.values)near(x,std::round(x));}
 std::optional<double> mixedBest;for(int x=-2;x<=4;++x){double lower=-2,upper=4;bool valid=true;for(const auto& row:q.constraints){const double rem=row.rhs-row.coefficients[0]*x,coef=row.coefficients[1];if(coef==0){if(row.relation==lp::Relation::LessEqual?rem<0:rem>0)valid=false;continue;}const double threshold=rem/coef;const bool atMost=(row.relation==lp::Relation::LessEqual)==(coef>0);if(atMost)upper=std::min(upper,threshold);else lower=std::max(lower,threshold);}if(!valid || lower>upper+1e-8)continue;const bool high=(q.sense==lp::ObjectiveSense::Maximize)==(q.objective[1]>0);const double y=high?upper:lower;const double value=q.objective[0]*x+q.objective[1]*y;if(!mixedBest || (q.sense==lp::ObjectiveSense::Maximize?value>*mixedBest:value<*mixedBest))mixedBest=value;}
 const auto mixed=integer::solve({q,{true,false}});check(bool(mixed.objective)==bool(mixedBest));if(mixedBest){near(*mixed.objective,*mixedBest);check(feasible(q,mixed.values));near(mixed.values[0],std::round(mixed.values[0]));}}

 auto zero=lp::LpProblem::blank(1,1);zero.objective={0};zero.constraints={{{0},lp::Relation::LessEqual,-1}};check(integer::solve({zero,{true}}).status==integer::Status::Infeasible);
 auto unbounded=lp::LpProblem::blank(1,1);unbounded.objective={1};unbounded.constraints={{{1},lp::Relation::GreaterEqual,0}};check(integer::solve({unbounded,{true}}).status==integer::Status::UnboundedRelaxation);
 auto fixed=lp::LpProblem::blank(2,1);fixed.objective={3,2};fixed.variables[0].lowerBound=2;fixed.variables[0].upperBound=2;fixed.variables[1].lowerBound=-1;fixed.variables[1].upperBound=-1;fixed.constraints={{{1,1},lp::Relation::Equal,1}};r=integer::solve({fixed,{true,true}});check(r.status==integer::Status::Optimal);near(*r.objective,4);
 fixed.constraints[0].rhs=2;check(integer::solve({fixed,{true,true}}).status==integer::Status::Infeasible);
 // Exact regression for the legacy display solver's infeasible-origin case.
 auto legacy=lp::LpProblem::blank(2,3);legacy.objective={-3,-2};for(auto& v:legacy.variables){v.lowerBound=-2;v.upperBound=4;}legacy.constraints={{{1,3},lp::Relation::LessEqual,-3},{{-1,-1},lp::Relation::GreaterEqual,1},{{2,1},lp::Relation::GreaterEqual,0}};r=integer::solve({legacy,{true,true}});check(r.status==integer::Status::Optimal);check(feasible(legacy,r.values));
 std::cout<<"Integer:300 integer grid and300 mixed interval independently enumerated bounded models, mixed/free/negative/fixed bounds, zero rows, unbounded relaxations guided branch/frontier/pruning controls and terminal limits passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
